    Paper(
      id: 'dqn',
      title: 'Playing Atari with Deep Reinforcement Learning',
      authors: ['Volodymyr Mnih', 'Koray Kavukcuoglu', 'David Silver', 'Alex Graves'],
      year: 2013,
      abstractText: 'We present the first deep learning model to successfully learn control policies directly from high-dimensional sensory input using reinforcement learning. The model is a convolutional neural network, trained with a variant of Q-learning, whose input is raw pixels and whose output is a value function estimating future rewards.',
      tags: ['RL', 'Deep Learning'],
